package com.chineselearning;

import org.springframework.jdbc.core.simple.JdbcClient;

final class FoundationTestSupport {
    private FoundationTestSupport() {}
    // Downstream feature fixtures have already studied Pinyin. No activity events are
    // seeded, so each test can assert only the events generated by its own actions.
    static void graduate(JdbcClient jdbc,String email) {
        jdbc.sql("""
            INSERT INTO foundation_progress(user_id,slug,section_index,lesson_version,version,completed_at,updated_at)
            SELECT u.id,f.slug,0,f.version,1,now(),now() FROM users u CROSS JOIN foundation_lessons f
            WHERE u.email=:email AND f.published
            ON CONFLICT(user_id,slug) DO NOTHING
            """).param("email",email).update();
    }
}
